reply:
```turtle
@prefix ht:   <http://example.org/onto/hypertension#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

<http://example.org/onto/hypertension> a owl:Ontology ;
    rdfs:label "Hypertension Ontology"@en ;
    rdfs:comment "An ontology of hypertension classification, etiology, measurement, treatment, risk factors and target-organ damage, modeled from a corpus of clinical and guideline text."@en .

#################################################################
# TOP-LEVEL KIND DISJOINTNESS
#################################################################

owl:AllDisjointClasses [ owl:members ( ht:BloodPressureReading ht:Hypertension ht:Antihypertensive
    ht:SecondaryCause ht:TargetOrganDamage ht:RiskFactor ht:BloodPressureMeasurementMethod ) ] .

#################################################################
# MEASUREMENT AXIS
#################################################################

ht:BloodPressureReading a owl:Class ;
    rdfs:label "Blood Pressure Reading"@en ;
    skos:definition "A measured pair of systolic and diastolic values, expressed in millimetres of mercury, obtained by some measurement method."@en ;
    rdfs:subClassOf [ a owl:Restriction ; owl:onProperty ht:hasSystolicValue ;
          owl:qualifiedCardinality 1 ; owl:onDataRange xsd:integer ] ,
        [ a owl:Restriction ; owl:onProperty ht:hasDiastolicValue ;
          owl:qualifiedCardinality 1 ; owl:onDataRange xsd:integer ] .

ht:hasSystolicValue a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has systolic value"@en ;
    skos:definition "The maximum arterial pressure during one heartbeat, in mmHg."@en ;
    rdfs:domain ht:BloodPressureReading ; rdfs:range xsd:integer .

ht:hasDiastolicValue a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has diastolic value"@en ;
    skos:definition "The minimum arterial pressure between heartbeats, in mmHg."@en ;
    rdfs:domain ht:BloodPressureReading ; rdfs:range xsd:integer .

ht:hasBloodPressureCategory a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has blood pressure category"@en ;
    skos:definition "Relates a blood pressure reading to the single ACC/AHA-2017 category it falls into."@en ;
    rdfs:domain ht:BloodPressureReading ; rdfs:range ht:BloodPressureCategory ;
    owl:inverseOf ht:isBloodPressureCategoryOf .

ht:isBloodPressureCategoryOf a owl:ObjectProperty ;
    rdfs:label "is blood pressure category of"@en ;
    rdfs:domain ht:BloodPressureCategory ; rdfs:range ht:BloodPressureReading .

#################################################################
# BLOOD PRESSURE CATEGORIES (ACC/AHA 2017 scheme, genus = reading)
#################################################################

ht:BloodPressureCategory a owl:Class ;
    rdfs:label "Blood Pressure Category"@en ;
    skos:definition "One of the ACC/AHA-2017 classification bands into which a blood pressure reading falls."@en ;
    rdfs:subClassOf ht:BloodPressureReading ;
    rdfs:comment "This ontology models exactly one classification scheme, the 2017 ACC/AHA scheme. Competing schemes exist: ESC/ESH (2018/2023) uses Optimal/Normal/High-normal/Grade1/Grade2/Grade3 with a 140/90 mmHg diagnostic threshold; JNC 7 uses Normal/Prehypertension/Stage1/Stage2 with a 140/90 mmHg threshold; WHO and ISH (2020) also use a 140/90 mmHg threshold; the 2024 ESC guideline introduces a 120-139/70-89 'Elevated Blood Pressure' band. These are NOT modeled as separate class trees per the scope clamp."@en .

ht:NormalBloodPressure a owl:Class ;
    rdfs:label "Normal Blood Pressure"@en ;
    rdfs:subClassOf ht:BloodPressureCategory ;
    skos:definition "A reading with systolic pressure below 120 mmHg and diastolic pressure below 80 mmHg."@en ;
    owl:equivalentClass [ owl:intersectionOf ( ht:BloodPressureReading
        [ a owl:Restriction ; owl:onProperty ht:hasSystolicValue ; owl:someValuesFrom
            [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
              owl:withRestrictions ( [ xsd:maxExclusive 120 ] ) ] ]
        [ a owl:Restriction ; owl:onProperty ht:hasDiastolicValue ; owl:someValuesFrom
            [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
              owl:withRestrictions ( [ xsd:maxExclusive 80 ] ) ] ] ) ] .

ht:ElevatedBloodPressure a owl:Class ;
    rdfs:label "Elevated Blood Pressure"@en ;
    rdfs:subClassOf ht:BloodPressureCategory ;
    skos:definition "A reading with systolic pressure of 120 to 129 mmHg and diastolic pressure below 80 mmHg; formerly termed prehypertension."@en ;
    skos:altLabel "Prehypertension"@en ;
    owl:equivalentClass [ owl:intersectionOf ( ht:BloodPressureReading
        [ a owl:Restriction ; owl:onProperty ht:hasSystolicValue ; owl:someValuesFrom
            [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
              owl:withRestrictions ( [ xsd:minInclusive 120 ] [ xsd:maxInclusive 129 ] ) ] ]
        [ a owl:Restriction ; owl:onProperty ht:hasDiastolicValue ; owl:someValuesFrom
            [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
              owl:withRestrictions ( [ xsd:maxExclusive 80 ] ) ] ] ) ] .

ht:Stage1Hypertension a owl:Class ;
    rdfs:label "Stage 1 Hypertension"@en ;
    rdfs:subClassOf ht:BloodPressureCategory ;
    skos:definition "A reading with systolic pressure of 130 to 139 mmHg or diastolic pressure of 80 to 89 mmHg."@en ;
    owl:equivalentClass [ owl:unionOf (
        [ owl:intersectionOf ( ht:BloodPressureReading
            [ a owl:Restriction ; owl:onProperty ht:hasSystolicValue ; owl:someValuesFrom
                [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
                  owl:withRestrictions ( [ xsd:minInclusive 130 ] [ xsd:maxInclusive 139 ] ) ] ] ) ]
        [ owl:intersectionOf ( ht:BloodPressureReading
            [ a owl:Restriction ; owl:onProperty ht:hasDiastolicValue ; owl:someValuesFrom
                [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
                  owl:withRestrictions ( [ xsd:minInclusive 80 ] [ xsd:maxInclusive 89 ] ) ] ] ) ]
    ) ] .

ht:Stage2Hypertension a owl:Class ;
    rdfs:label "Stage 2 Hypertension"@en ;
    rdfs:subClassOf ht:BloodPressureCategory ;
    skos:definition "A reading with systolic pressure of 140 mmHg or greater or diastolic pressure of 90 mmHg or greater."@en ;
    owl:equivalentClass [ owl:unionOf (
        [ owl:intersectionOf ( ht:BloodPressureReading
            [ a owl:Restriction ; owl:onProperty ht:hasSystolicValue ; owl:someValuesFrom
                [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
                  owl:withRestrictions ( [ xsd:minInclusive 140 ] ) ] ] ) ]
        [ owl:intersectionOf ( ht:BloodPressureReading
            [ a owl:Restriction ; owl:onProperty ht:hasDiastolicValue ; owl:someValuesFrom
                [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
                  owl:withRestrictions ( [ xsd:minInclusive 90 ] ) ] ] ) ]
    ) ] .

owl:AllDisjointClasses [ owl:members ( ht:NormalBloodPressure ht:ElevatedBloodPressure
    ht:Stage1Hypertension ht:Stage2Hypertension ) ] .

#################################################################
# MEASUREMENT METHOD
#################################################################

ht:BloodPressureMeasurementMethod a owl:Class ;
    rdfs:label "Blood Pressure Measurement Method"@en ;
    skos:definition "A technique or setting used to obtain a blood pressure reading."@en .

ht:AuscultatoryMethod a owl:Class ;
    rdfs:label "Auscultatory Method"@en ;
    rdfs:subClassOf ht:BloodPressureMeasurementMethod ;
    skos:definition "Measurement using a sphygmomanometer and stethoscope, identifying systolic and diastolic pressure from Korotkoff sounds."@en .

ht:OscillometricMethod a owl:Class ;
    rdfs:label "Oscillometric Method"@en ;
    rdfs:subClassOf ht:BloodPressureMeasurementMethod ;
    skos:definition "Automated measurement that derives systolic, diastolic and mean arterial pressure from oscillations in cuff pressure."@en .

ht:OfficeBloodPressureMeasurement a owl:Class ;
    rdfs:label "Office Blood Pressure Measurement"@en ;
    rdfs:subClassOf ht:BloodPressureMeasurementMethod ;
    skos:definition "Blood pressure measurement taken in a clinic or office setting."@en ;
    skos:altLabel "Clinic Blood Pressure Measurement"@en .

ht:AmbulatoryBloodPressureMonitoring a owl:Class ;
    rdfs:label "Ambulatory Blood Pressure Monitoring"@en ;
    rdfs:subClassOf ht:BloodPressureMeasurementMethod ;
    skos:definition "Measurement of blood pressure at regular intervals over a full day-night cycle outside the clinical setting."@en ;
    skos:altLabel "ABPM"@en .

ht:HomeBloodPressureMonitoring a owl:Class ;
    rdfs:label "Home Blood Pressure Monitoring"@en ;
    rdfs:subClassOf ht:BloodPressureMeasurementMethod ;
    skos:definition "Patient self-measurement of blood pressure at home using a validated device."@en ;
    skos:altLabel "HBPM"@en .

owl:AllDisjointClasses [ owl:members ( ht:AuscultatoryMethod ht:OscillometricMethod
    ht:OfficeBloodPressureMeasurement ht:AmbulatoryBloodPressureMonitoring ht:HomeBloodPressureMonitoring ) ] .

ht:hasMeasurementMethod a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has measurement method"@en ;
    skos:definition "Relates a blood pressure reading to the method by which it was obtained."@en ;
    rdfs:domain ht:BloodPressureReading ; rdfs:range ht:BloodPressureMeasurementMethod ;
    owl:inverseOf ht:isMeasurementMethodOf .

ht:isMeasurementMethodOf a owl:ObjectProperty ;
    rdfs:label "is measurement method of"@en ;
    rdfs:domain ht:BloodPressureMeasurementMethod ; rdfs:range ht:BloodPressureReading .

#################################################################
# HYPERTENSION (disease) AND DIAGNOSTIC THRESHOLD
#################################################################

ht:Hypertension a owl:Class ;
    rdfs:label "Hypertension"@en ;
    skos:definition "A chronic medical condition characterized by sustained elevation of arterial blood pressure."@en ;
    skos:altLabel "High Blood Pressure"@en ;
    rdfs:subClassOf [ a owl:Restriction ; owl:onProperty ht:hasBloodPressureCategory ;
        owl:someValuesFrom ht:BloodPressureCategory ] .

ht:hasDiagnosticSystolicThreshold a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has diagnostic systolic threshold"@en ;
    skos:definition "The systolic blood pressure value (mmHg) at or above which a guideline diagnoses hypertension."@en ;
    rdfs:domain ht:Hypertension ; rdfs:range xsd:integer ;
    rdfs:comment "This single functional property deliberately holds one of two competing corpus-documented values: the 2017 ACC/AHA guideline sets this threshold at 130 mmHg, whereas the ESC/ESH, JNC 7, WHO and ISH guidelines set it at 140 mmHg. The ontology records the conflict here rather than creating per-guideline threshold subclasses."@en .

ht:hasSecondaryCause a owl:ObjectProperty ;
    rdfs:label "has secondary cause"@en ;
    skos:definition "Relates a secondary hypertension to its identifiable underlying cause."@en ;
    rdfs:domain ht:SecondaryHypertension ; rdfs:range ht:SecondaryCause ;
    owl:inverseOf ht:isSecondaryCauseOf .

ht:isSecondaryCauseOf a owl:ObjectProperty ;
    rdfs:label "is secondary cause of"@en ;
    rdfs:domain ht:SecondaryCause ; rdfs:range ht:SecondaryHypertension .

ht:hasTargetOrganDamage a owl:ObjectProperty ;
    rdfs:label "has target organ damage"@en ;
    skos:definition "Relates a hypertensive condition to a form of hypertension-mediated organ damage it has produced."@en ;
    rdfs:domain ht:Hypertension ; rdfs:range ht:TargetOrganDamage ;
    owl:inverseOf ht:isTargetOrganDamageOf .

ht:isTargetOrganDamageOf a owl:ObjectProperty ;
    rdfs:label "is target organ damage of"@en ;
    rdfs:domain ht:TargetOrganDamage ; rdfs:range ht:Hypertension .

ht:hasAntihypertensive a owl:ObjectProperty ;
    rdfs:label "has antihypertensive"@en ;
    skos:definition "Relates a hypertensive condition to a class of medication used to treat it."@en ;
    rdfs:domain ht:Hypertension ; rdfs:range ht:Antihypertensive ;
    owl:inverseOf ht:isAntihypertensiveOf .

ht:isAntihypertensiveOf a owl:ObjectProperty ;
    rdfs:label "is antihypertensive of"@en ;
    rdfs:domain ht:Antihypertensive ; rdfs:range ht:Hypertension .

ht:hasRiskFactor a owl:ObjectProperty ;
    rdfs:label "has risk factor"@en ;
    skos:definition "Relates a hypertensive condition to a factor that increases risk of its development."@en ;
    rdfs:domain ht:Hypertension ; rdfs:range ht:RiskFactor ;
    owl:inverseOf ht:isRiskFactorOf .

ht:isRiskFactorOf a owl:ObjectProperty ;
    rdfs:label "is risk factor of"@en ;
    rdfs:domain ht:RiskFactor ; rdfs:range ht:Hypertension .

#################################################################
# HYPERTENSION SUBTYPES (etiology)
#################################################################

ht:PrimaryHypertension a owl:Class ;
    rdfs:label "Primary Hypertension"@en ;
    rdfs:subClassOf ht:Hypertension ;
    skos:definition "Hypertension with no single identifiable cause, accounting for the great majority of cases and arising from interacting genetic and environmental factors."@en ;
    skos:altLabel "Essential Hypertension"@en , "Idiopathic Hypertension"@en .

ht:SecondaryHypertension a owl:Class ;
    rdfs:label "Secondary Hypertension"@en ;
    rdfs:subClassOf ht:Hypertension ;
    skos:definition "Hypertension that is elevated blood pressure secondary to an identifiable, and frequently correctable, underlying cause."@en ;
    skos:altLabel "Inessential Hypertension"@en ;
    owl:equivalentClass [ owl:intersectionOf ( ht:Hypertension
        [ a owl:Restriction ; owl:onProperty ht:hasSecondaryCause ; owl:someValuesFrom ht:SecondaryCause ] ) ] .

owl:AllDisjointClasses [ owl:members ( ht:PrimaryHypertension ht:SecondaryHypertension ) ] .

ht:IsolatedSystolicHypertension a owl:Class ;
    rdfs:label "Isolated Systolic Hypertension"@en ;
    rdfs:subClassOf ht:Hypertension ;
    skos:definition "Hypertension characterized by a disproportionate rise in systolic pressure with a preserved or low diastolic pressure, producing a widened pulse pressure, and predominating in older adults due to arterial stiffening."@en ;
    rdfs:comment "Traditionally defined as systolic pressure above 140 mmHg with diastolic below 90 mmHg; under the 2017 ACC/AHA guideline a systolic pressure of 130 mmHg is now considered hypertensive at all ages."@en .

ht:WhiteCoatHypertension a owl:Class ;
    rdfs:label "White Coat Hypertension"@en ;
    rdfs:subClassOf ht:Hypertension ;
    skos:definition "A phenotype in which blood pressure is consistently elevated in a clinical setting but normal out-of-office, believed due to anxiety during the clinic visit."@en ;
    skos:altLabel "White Coat Syndrome"@en , "White Coat Effect"@en .

ht:MaskedHypertension a owl:Class ;
    rdfs:label "Masked Hypertension"@en ;
    rdfs:subClassOf ht:Hypertension ;
    skos:definition "A phenotype in which blood pressure is normal in the clinic but consistently elevated out-of-office, carrying cardiovascular risk similar to sustained hypertension."@en ;
    skos:altLabel "MH"@en .

owl:AllDisjointClasses [ owl:members ( ht:WhiteCoatHypertension ht:MaskedHypertension ) ] .

ht:ResistantHypertension a owl:Class ;
    rdfs:label "Resistant Hypertension"@en ;
    rdfs:subClassOf ht:Hypertension ;
    skos:definition "Blood pressure that remains above goal despite adherence to three suitably dosed antihypertensive medications of different classes, one of which is a diuretic, or blood pressure that requires four or more agents, after confirming adherence and excluding the white-coat effect."@en .

ht:HypertensiveCrisis a owl:Class ;
    rdfs:label "Hypertensive Crisis"@en ;
    rdfs:subClassOf ht:Hypertension ;
    skos:definition "A severe, acute elevation of blood pressure, conventionally a systolic pressure of 180 mmHg or more or a diastolic pressure of 120 mmHg or more, classified into urgency and emergency by the presence or absence of acute target-organ damage rather than by the blood pressure value itself."@en .

ht:HypertensiveEmergency a owl:Class ;
    rdfs:label "Hypertensive Emergency"@en ;
    rdfs:subClassOf ht:HypertensiveCrisis ;
    skos:definition "A hypertensive crisis accompanied by acute hypertension-mediated organ damage, representing a life-threatening condition requiring immediate, controlled blood pressure reduction."@en ;
    owl:equivalentClass [ owl:intersectionOf ( ht:HypertensiveCrisis
        [ a owl:Restriction ; owl:onProperty ht:hasTargetOrganDamage ; owl:someValuesFrom ht:TargetOrganDamage ] ) ] .

ht:HypertensiveUrgency a owl:Class ;
    rdfs:label "Hypertensive Urgency"@en ;
    rdfs:subClassOf ht:HypertensiveCrisis ;
    skos:definition "A hypertensive crisis without evidence of acute target-organ damage, typically managed with gradual oral blood pressure reduction."@en .

owl:AllDisjointClasses [ owl:members ( ht:HypertensiveUrgency ht:HypertensiveEmergency ) ] .

#################################################################
# SECONDARY CAUSES
#################################################################

ht:SecondaryCause a owl:Class ;
    rdfs:label "Secondary Cause"@en ;
    skos:definition "An identifiable underlying medical condition, medication, or substance that produces secondary hypertension."@en .

ht:RenalCause a owl:Class ;
    rdfs:label "Renal Cause"@en ;
    rdfs:subClassOf ht:SecondaryCause ;
    skos:definition "A secondary cause of hypertension originating in the kidney, the most common category of secondary cause."@en .

ht:RenalParenchymalDisease a owl:Class ;
    rdfs:label "Renal Parenchymal Disease"@en ;
    rdfs:subClassOf ht:RenalCause ;
    skos:definition "Disease of the kidney tissue itself, including diabetic nephropathy, glomerulonephritis, interstitial disorders and polycystic kidney disease, that causes secondary hypertension."@en .

ht:RenovascularDisease a owl:Class ;
    rdfs:label "Renovascular Disease"@en ;
    rdfs:subClassOf ht:RenalCause ;
    skos:definition "Disease of the renal blood vessels that causes secondary hypertension."@en ;
    skos:altLabel "Renovascular Hypertension"@en .

ht:RenalArteryStenosis a owl:Class ;
    rdfs:label "Renal Artery Stenosis"@en ;
    rdfs:subClassOf ht:RenovascularDisease ;
    skos:definition "Narrowing of a renal artery that produces secondary hypertension by renovascular mechanisms."@en ;
    skos:altLabel "Renal Artery Narrowing"@en .

ht:EndocrineCause a owl:Class ;
    rdfs:label "Endocrine Cause"@en ;
    rdfs:subClassOf ht:SecondaryCause ;
    skos:definition "A hormonal disorder that causes secondary hypertension."@en .

ht:PrimaryAldosteronism a owl:Class ;
    rdfs:label "Primary Aldosteronism"@en ;
    rdfs:subClassOf ht:EndocrineCause ;
    skos:definition "Autonomous overproduction of aldosterone by the adrenal glands, due to an adenoma or bilateral hyperplasia, that accounts for most endocrine-related secondary hypertension."@en ;
    skos:altLabel "Conn's Syndrome"@en , "Hyperaldosteronism"@en .

ht:Pheochromocytoma a owl:Class ;
    rdfs:label "Pheochromocytoma"@en ;
    rdfs:subClassOf ht:EndocrineCause ;
    skos:definition "A tumor causing excessive secretion of norepinephrine and epinephrine, which promotes vasoconstriction and raises blood pressure."@en .

ht:CushingSyndrome a owl:Class ;
    rdfs:label "Cushing Syndrome"@en ;
    rdfs:subClassOf ht:EndocrineCause ;
    skos:definition "Excess glucocorticoid production causing secondary hypertension."@en .

ht:Hyperthyroidism a owl:Class ;
    rdfs:label "Hyperthyroidism"@en ;
    rdfs:subClassOf ht:EndocrineCause ;
    skos:definition "Excess thyroid hormone production that can cause secondary hypertension."@en .

ht:Hypothyroidism a owl:Class ;
    rdfs:label "Hypothyroidism"@en ;
    rdfs:subClassOf ht:EndocrineCause ;
    skos:definition "Deficient thyroid hormone production that can cause secondary hypertension."@en .

ht:PrimaryHyperparathyroidism a owl:Class ;
    rdfs:label "Primary Hyperparathyroidism"@en ;
    rdfs:subClassOf ht:EndocrineCause ;
    skos:definition "Excess parathyroid hormone production recognised as a contributor to secondary hypertension."@en .

owl:AllDisjointClasses [ owl:members ( ht:PrimaryAldosteronism ht:Pheochromocytoma ht:CushingSyndrome
    ht:Hyperthyroidism ht:Hypothyroidism ht:PrimaryHyperparathyroidism ) ] .

ht:VascularCause a owl:Class ;
    rdfs:label "Vascular Cause"@en ;
    rdfs:subClassOf ht:SecondaryCause ;
    skos:definition "A structural vascular abnormality that causes secondary hypertension, typically affecting younger patients."@en .

ht:AorticCoarctation a owl:Class ;
    rdfs:label "Aortic Coarctation"@en ;
    rdfs:subClassOf ht:VascularCause ;
    skos:definition "A congenital narrowing of the aorta that causes secondary hypertension, typically presenting in younger patients."@en ;
    skos:altLabel "Coarctation of the Aorta"@en .

ht:ObstructiveSleepApnea a owl:Class ;
    rdfs:label "Obstructive Sleep Apnea"@en ;
    rdfs:subClassOf ht:SecondaryCause ;
    skos:definition "A sleep-related breathing disorder recognised as one of the most common causes of secondary hypertension."@en ;
    skos:altLabel "OSA"@en .

ht:DrugInducedHypertension a owl:Class ;
    rdfs:label "Drug Induced Hypertension"@en ;
    rdfs:subClassOf ht:SecondaryCause ;
    skos:definition "Secondary hypertension caused by a medication or substance, including NSAIDs, sympathomimetic decongestants, stimulants, corticosteroids, oral contraceptives, immunosuppressants, licorice-derived mineralocorticoid-like substances, and recreational stimulants such as cocaine and methamphetamine."@en .

owl:AllDisjointClasses [ owl:members ( ht:RenalCause ht:EndocrineCause ht:VascularCause
    ht:ObstructiveSleepApnea ht:DrugInducedHypertension ) ] .

#################################################################
# TARGET ORGAN DAMAGE
#################################################################

ht:TargetOrganDamage a owl:Class ;
    rdfs:label "Target Organ Damage"@en ;
    skos:definition "Structural or functional damage to an organ system resulting from chronic or acute hypertension."@en ;
    skos:altLabel "Hypertension-Mediated Organ Damage"@en .

ht:HypertensiveHeartDisease a owl:Class ;
    rdfs:label "Hypertensive Heart Disease"@en ;
    rdfs:subClassOf ht:TargetOrganDamage ;
    skos:definition "Structural and functional changes in the left ventricle, left atrium, and coronary arteries resulting from chronic blood pressure elevation."@en .

ht:LeftVentricularHypertrophy a owl:Class ;
    rdfs:label "Left Ventricular Hypertrophy"@en ;
    rdfs:subClassOf ht:HypertensiveHeartDisease ;
    skos:definition "Thickening of the left ventricular wall in compensatory response to chronic pressure overload; the hallmark structural manifestation of hypertensive cardiac damage."@en .

ht:HypertensiveRetinopathy a owl:Class ;
    rdfs:label "Hypertensive Retinopathy"@en ;
    rdfs:subClassOf ht:TargetOrganDamage ;
    skos:definition "Damage to the retina and retinal circulation caused by sustained or abrupt elevation of blood pressure, visible on dilated eye examination."@en ;
    rdfs:comment "The corpus describes four Keith-Wagener-Barker severity grades; per the scope clamp these grades are not modeled as separate classes, only the retinal findings they comprise."@en .

ht:RetinalFinding a owl:Class ;
    rdfs:label "Retinal Finding"@en ;
    skos:definition "A specific abnormality of the retinal vasculature or tissue observed on fundoscopic examination in hypertensive retinopathy."@en .

ht:ArteriolarNarrowing a owl:Class ;
    rdfs:label "Arteriolar Narrowing"@en ;
    rdfs:subClassOf ht:RetinalFinding ;
    skos:definition "Generalized or focal narrowing of the retinal arterioles."@en .

ht:ArteriovenousNicking a owl:Class ;
    rdfs:label "Arteriovenous Nicking"@en ;
    rdfs:subClassOf ht:RetinalFinding ;
    skos:definition "Compression of a retinal vein where a sclerotic arteriole crosses it."@en ;
    skos:altLabel "AV Nipping"@en .

ht:RetinalHemorrhage a owl:Class ;
    rdfs:label "Retinal Hemorrhage"@en ;
    rdfs:subClassOf ht:RetinalFinding ;
    skos:definition "Bleeding into the retinal tissue, including flame-shaped and blot hemorrhages, from breakdown of the blood-retinal barrier."@en .

ht:CottonWoolSpot a owl:Class ;
    rdfs:label "Cotton Wool Spot"@en ;
    rdfs:subClassOf ht:RetinalFinding ;
    skos:definition "A retinal ischemic lesion appearing as a white, fluffy patch on fundoscopy."@en .

ht:HardExudate a owl:Class ;
    rdfs:label "Hard Exudate"@en ;
    rdfs:subClassOf ht:RetinalFinding ;
    skos:definition "Lipid deposits leaked into the retinal tissue through a disrupted blood-retinal barrier."@en .

ht:Papilledema a owl:Class ;
    rdfs:label "Papilledema"@en ;
    rdfs:subClassOf ht:RetinalFinding ;
    skos:definition "Swelling of the optic disc, the most severe retinal finding, indicating malignant hypertensive retinopathy."@en ;
    skos:altLabel "Optic Disc Edema"@en .

owl:AllDisjointClasses [ owl:members ( ht:ArteriolarNarrowing ht:ArteriovenousNicking
    ht:RetinalHemorrhage ht:CottonWoolSpot ht:HardExudate ht:Papilledema ) ] .

ht:hasRetinalFinding a owl:ObjectProperty ;
    rdfs:label "has retinal finding"@en ;
    skos:definition "Relates hypertensive retinopathy to a specific retinal abnormality observed."@en ;
    rdfs:domain ht:HypertensiveRetinopathy ; rdfs:range ht:RetinalFinding ;
    owl:inverseOf ht:isRetinalFindingOf .

ht:isRetinalFindingOf a owl:ObjectProperty ;
    rdfs:label "is retinal finding of"@en ;
    rdfs:domain ht:RetinalFinding ; rdfs:range ht:HypertensiveRetinopathy .

ht:HypertensiveNephropathy a owl:Class ;
    rdfs:label "Hypertensive Nephropathy"@en ;
    rdfs:subClassOf ht:TargetOrganDamage ;
    skos:definition "Kidney damage attributable to chronic hypertension, characterized by nephrosclerosis: hardening and thickening of renal small vessels, glomeruli, tubules and interstitial tissue, reducing blood and oxygen supply and progressively impairing filtration."@en ;
    skos:altLabel "Hypertensive Kidney Disease"@en , "Nephrosclerosis"@en .

ht:HypertensiveEncephalopathy a owl:Class ;
    rdfs:label "Hypertensive Encephalopathy"@en ;
    rdfs:subClassOf ht:TargetOrganDamage ;
    skos:definition "Acute brain swelling and dysfunction caused by severely elevated blood pressure, presenting with headache, confusion, or visual disturbance."@en .

ht:Stroke a owl:Class ;
    rdfs:label "Stroke"@en ;
    rdfs:subClassOf ht:TargetOrganDamage ;
    skos:definition "Ischemic or hemorrhagic cerebrovascular injury resulting from bursting or blockage of arteries supplying the brain, caused by sustained or acute hypertension."@en .

owl:AllDisjointClasses [ owl:members ( ht:HypertensiveHeartDisease ht:HypertensiveRetinopathy
    ht:HypertensiveNephropathy ht:HypertensiveEncephalopathy ht:Stroke ) ] .

#################################################################
# RISK FACTORS
#################################################################

ht:RiskFactor a owl:Class ;
    rdfs:label "Risk Factor"@en ;
    skos:definition "A modifiable or non-modifiable factor that increases the risk of developing hypertension."@en .

ht:ModifiableRiskFactor a owl:Class ;
    rdfs:label "Modifiable Risk Factor"@en ;
    rdfs:subClassOf ht:RiskFactor ;
    skos:definition "A risk factor for hypertension that can be changed through behavior or intervention."@en .

ht:NonModifiableRiskFactor a owl:Class ;
    rdfs:label "Non Modifiable Risk Factor"@en ;
    rdfs:subClassOf ht:RiskFactor ;
    skos:definition "A risk factor for hypertension that cannot be changed, such as age, sex, race, or family history."@en .

owl:AllDisjointClasses [ owl:members ( ht:ModifiableRiskFactor ht:NonModifiableRiskFactor ) ] .

ht:ExcessSaltIntake a owl:Class ;
    rdfs:label "Excess Salt Intake"@en ;
    rdfs:subClassOf ht:ModifiableRiskFactor ;
    skos:definition "Dietary sodium intake in excess, a central modifiable risk factor for developing hypertension, to which 50-60% of patients are salt sensitive."@en .

ht:Obesity a owl:Class ;
    rdfs:label "Obesity"@en ;
    rdfs:subClassOf ht:ModifiableRiskFactor ;
    skos:definition "Excess body weight, a modifiable risk factor for hypertension; weight reduction alone can lower systolic pressure by 5 to 20 mmHg."@en .

ht:TobaccoUse a owl:Class ;
    rdfs:label "Tobacco Use"@en ;
    rdfs:subClassOf ht:ModifiableRiskFactor ;
    skos:definition "Smoking or other tobacco consumption, a modifiable risk factor for hypertension."@en ;
    skos:altLabel "Smoking"@en .

ht:PhysicalInactivity a owl:Class ;
    rdfs:label "Physical Inactivity"@en ;
    rdfs:subClassOf ht:ModifiableRiskFactor ;
    skos:definition "Lack of regular exercise, a modifiable risk factor for hypertension."@en .

ht:AlcoholUse a owl:Class ;
    rdfs:label "Alcohol Use"@en ;
    rdfs:subClassOf ht:ModifiableRiskFactor ;
    skos:definition "Consumption of alcohol, associated with increased blood pressure and a modifiable risk factor for hypertension."@en .

owl:AllDisjointClasses [ owl:members ( ht:ExcessSaltIntake ht:Obesity ht:TobaccoUse
    ht:PhysicalInactivity ht:AlcoholUse ) ] .

ht:AdvancedAge a owl:Class ;
    rdfs:label "Advanced Age"@en ;
    rdfs:subClassOf ht:NonModifiableRiskFactor ;
    skos:definition "Age above 60 years, a non-modifiable risk factor associated with hypertension prevalence rising to as much as 60% of the population."@en .

ht:FamilyHistoryOfHypertension a owl:Class ;
    rdfs:label "Family History Of Hypertension"@en ;
    rdfs:subClassOf ht:NonModifiableRiskFactor ;
    skos:definition "A family history of hypertension, a non-modifiable genetic risk factor."@en .

ht:Race a owl:Class ;
    rdfs:label "Race"@en ;
    rdfs:subClassOf ht:NonModifiableRiskFactor ;
    skos:definition "Racial background, a non-modifiable factor that influences hypertension risk and first-line treatment selection, for example between Black and non-Black populations."@en .

owl:AllDisjointClasses [ owl:members ( ht:AdvancedAge ht:FamilyHistoryOfHypertension ht:Race ) ] .

#################################################################
# ANTIHYPERTENSIVE DRUG CLASSES
#################################################################

ht:Antihypertensive a owl:Class ;
    rdfs:label "Antihypertensive"@en ;
    skos:definition "A class of medication used to lower blood pressure in the treatment of hypertension."@en .

ht:ThiazideDiuretic a owl:Class ;
    rdfs:label "Thiazide Diuretic"@en ;
    rdfs:subClassOf ht:Antihypertensive ;
    skos:definition "A first-line antihypertensive class that blocks sodium reabsorption in the distal convoluted tubule, promoting natriuresis and diuresis and reducing intravascular volume."@en ;
    skos:altLabel "Thiazide-type Diuretic"@en .

ht:AngiotensinConvertingEnzymeInhibitor a owl:Class ;
    rdfs:label "Angiotensin Converting Enzyme Inhibitor"@en ;
    rdfs:subClassOf ht:Antihypertensive ;
    skos:definition "A first-line antihypertensive class that inhibits the angiotensin-converting enzyme, reducing angiotensin II production and increasing bradykinin levels, leading to vasodilation."@en ;
    skos:altLabel "ACE Inhibitor"@en , "ACEI"@en .

ht:AngiotensinReceptorBlocker a owl:Class ;
    rdfs:label "Angiotensin Receptor Blocker"@en ;
    rdfs:subClassOf ht:Antihypertensive ;
    skos:definition "A first-line antihypertensive class that blocks the binding of angiotensin II to its receptor, producing vasodilation without affecting enzyme production."@en ;
    skos:altLabel "ARB"@en , "Angiotensin II Receptor Blocker"@en .

ht:CalciumChannelBlocker a owl:Class ;
    rdfs:label "Calcium Channel Blocker"@en ;
    rdfs:subClassOf ht:Antihypertensive ;
    skos:definition "A first-line antihypertensive class that inhibits calcium entry through L-type voltage-gated calcium channels in cardiac and vascular smooth muscle."@en ;
    skos:altLabel "CCB"@en .

ht:DihydropyridineCalciumChannelBlocker a owl:Class ;
    rdfs:label "Dihydropyridine Calcium Channel Blocker"@en ;
    rdfs:subClassOf ht:CalciumChannelBlocker ;
    skos:definition "A calcium channel blocker subtype that acts predominantly on vascular smooth muscle, causing peripheral vasodilation, and is preferred for treating hypertension."@en .

ht:NonDihydropyridineCalciumChannelBlocker a owl:Class ;
    rdfs:label "Non Dihydropyridine Calcium Channel Blocker"@en ;
    rdfs:subClassOf ht:CalciumChannelBlocker ;
    skos:definition "A calcium channel blocker subtype, such as verapamil and diltiazem, that primarily affects cardiac contractility and atrioventricular conduction, making it better suited to arrhythmia management."@en .

owl:AllDisjointClasses [ owl:members ( ht:DihydropyridineCalciumChannelBlocker
    ht:NonDihydropyridineCalciumChannelBlocker ) ] .

ht:BetaBlocker a owl:Class ;
    rdfs:label "Beta Blocker"@en ;
    rdfs:subClassOf ht:Antihypertensive ;
    skos:definition "An antihypertensive class that inhibits catecholamine binding to beta-adrenergic receptors, decreasing heart rate and myocardial oxygen consumption; no longer recommended as first-line therapy except for patients with a specific cardiac indication."@en .

owl:AllDisjointClasses [ owl:members ( ht:ThiazideDiuretic ht:AngiotensinConvertingEnzymeInhibitor
    ht:AngiotensinReceptorBlocker ht:CalciumChannelBlocker ht:BetaBlocker ) ] .
